import type { PbClient } from "../helpers/client.js";

const autodate = (name: string, onUpdate: boolean) => ({
  name,
  type: "autodate",
  onCreate: true,
  onUpdate,
});

/**
 * Create a comprehensive schema exercising every PocketBase field type and the
 * relational/edge features a generator must handle: self-referential relations,
 * a second auth collection, an autogenerated field, a custom id, a minSelect
 * relation, a unique-indexed 1:1 relation, a complex view, and domain-restricted
 * email/url. Returns the created collections by key.
 */
export async function defineSchema(pb: PbClient) {
  // PocketBase ships a default `users` collection — remove it for a fully
  // controlled schema.
  await pb.deleteCollection("users");

  const authors = await pb.createCollection({
    name: "authors",
    type: "auth",
    fields: [
      { name: "nickname", type: "text", required: false, max: 80 },
      { name: "bio", type: "editor", required: false },
      { name: "age", type: "number", required: false, onlyInt: true, min: 0, max: 150 },
      { name: "website", type: "url", required: false },
      autodate("created", false),
      autodate("updated", true),
    ],
  });

  // A second auth collection (multiple auth collections must both generate).
  const moderators = await pb.createCollection({
    name: "moderators",
    type: "auth",
    fields: [
      { name: "level", type: "number", required: false, onlyInt: true, min: 1, max: 5 },
      autodate("created", false),
    ],
  });

  // Self-referential relation: categories.parent -> categories. The parent's
  // collectionId is only known after creation, so create then patch it in.
  const categories = await pb.createCollection({
    name: "categories",
    type: "base",
    fields: [
      { name: "name", type: "text", required: true, min: 2, max: 50 },
      { name: "slug", type: "text", required: true, pattern: "^[a-z0-9-]+$" },
      { name: "weight", type: "number", required: false, min: 0 },
      autodate("created", false),
      autodate("updated", true),
    ],
  });
  await pb.updateCollection(categories.id, {
    fields: [
      ...categories.fields,
      { name: "parent", type: "relation", required: false, maxSelect: 1, collectionId: categories.id, cascadeDelete: false },
    ],
  });

  const posts = await pb.createCollection({
    name: "posts",
    type: "base",
    fields: [
      { name: "title", type: "text", required: true, min: 3, max: 120 },
      // autogenerated slug -> optional on create in the Record schema
      { name: "slug", type: "text", required: true, pattern: "^[a-z0-9-]+$", autogeneratePattern: "[a-z0-9]{10}" },
      { name: "content", type: "editor", required: false },
      { name: "views", type: "number", required: false, onlyInt: true, min: 0 },
      { name: "score", type: "number", required: false, min: -10, max: 10 },
      { name: "featured", type: "bool", required: false },
      {
        name: "status",
        type: "select",
        required: true,
        maxSelect: 1,
        values: ["draft", "published", "archived"],
      },
      { name: "tags", type: "select", required: false, maxSelect: 4, values: ["tech", "life", "news", "misc"] },
      { name: "author", type: "relation", required: true, maxSelect: 1, collectionId: authors.id, cascadeDelete: false },
      { name: "contributors", type: "relation", required: false, maxSelect: 5, collectionId: authors.id, cascadeDelete: false },
      { name: "category", type: "relation", required: false, maxSelect: 1, collectionId: categories.id, cascadeDelete: false },
      { name: "cover", type: "file", required: false, maxSelect: 1, maxSize: 5242880 },
      { name: "gallery", type: "file", required: false, maxSelect: 6, maxSize: 5242880 },
      // domain-restricted url + email
      { name: "homepage", type: "url", required: false, onlyDomains: ["example.com"] },
      { name: "contact_email", type: "email", required: false, onlyDomains: ["example.com"] },
      { name: "publish_date", type: "date", required: false },
      { name: "metadata", type: "json", required: false, maxSize: 2000000 },
      { name: "geo", type: "geoPoint", required: false },
      autodate("created", false),
      autodate("updated", true),
    ],
  });

  // minSelect relation: a team must have 2..5 members.
  // `reviewers` is the *optional* counterpart — PocketBase lets it stay empty
  // and returns `[]`, so the generated schema must not carry a `.min()` floor.
  const teams = await pb.createCollection({
    name: "teams",
    type: "base",
    fields: [
      { name: "name", type: "text", required: true, min: 1 },
      { name: "members", type: "relation", required: true, maxSelect: 5, minSelect: 2, collectionId: authors.id, cascadeDelete: false },
      { name: "reviewers", type: "relation", required: false, maxSelect: 5, minSelect: 2, collectionId: authors.id, cascadeDelete: false },
      autodate("created", false),
    ],
  });

  // Unique-indexed 1:1 relation -> authors.expand.profiles_via_author is a SINGLE object.
  const profiles = await pb.createCollection({
    name: "profiles",
    type: "base",
    indexes: ["CREATE UNIQUE INDEX `idx_profiles_author` ON `profiles` (`author`)"],
    fields: [
      { name: "author", type: "relation", required: true, maxSelect: 1, collectionId: authors.id, cascadeDelete: true },
      { name: "headline", type: "text", required: false },
      autodate("created", false),
    ],
  });

  // Custom record id (non-default length + pattern).
  const tokens = await pb.createCollection({
    name: "tokens",
    type: "base",
    fields: [
      {
        name: "id",
        type: "text",
        system: true,
        primaryKey: true,
        required: true,
        min: 10,
        max: 10,
        pattern: "^tk[a-z0-9]+$",
        autogeneratePattern: "tk[a-z0-9]{8}",
      },
      { name: "label", type: "text", required: true },
      autodate("created", false),
    ],
  });

  const comments = await pb.createCollection({
    name: "comments",
    type: "base",
    fields: [
      { name: "body", type: "text", required: true, min: 1 },
      { name: "post", type: "relation", required: true, maxSelect: 1, collectionId: posts.id, cascadeDelete: true },
      autodate("created", false),
    ],
  });

  // Simple view (direct passthrough columns + a relation column).
  const postTitles = await pb.createCollection({
    name: "post_titles",
    type: "view",
    viewQuery: "SELECT id, title, status, author FROM posts",
  });

  // Complex view: LEFT JOIN + count aggregate (-> number onlyInt per PB inference).
  const postStats = await pb.createCollection({
    name: "post_stats",
    type: "view",
    viewQuery:
      "SELECT posts.id as id, posts.title as title, count(comments.id) as total_comments " +
      "FROM posts LEFT JOIN comments ON comments.post = posts.id GROUP BY posts.id",
  });

  return { authors, moderators, categories, posts, teams, profiles, tokens, comments, postTitles, postStats };
}

/** Seed records: full, minimal (empty sentinels), unicode, boundary numbers, deep json, relations. */
export async function seedData(pb: PbClient) {
  const tech = await pb.createRecord("categories", { name: "Technology", slug: "technology", weight: 10 });
  // child category referencing its parent (self-relation) — used for nested expand
  const web = await pb.createRecord("categories", { name: "Web", slug: "web", parent: tech.id });
  await pb.createRecord("categories", { name: "Life", slug: "life" });

  const alice = await pb.createRecord("authors", {
    nickname: "Alice",
    bio: "<p>hello</p>",
    age: 30,
    website: "https://alice.example",
    email: "alice@test.local",
    password: "password12345",
    passwordConfirm: "password12345",
    emailVisibility: true,
    verified: true,
  });
  const bob = await pb.createRecord("authors", {
    email: "bob@test.local",
    password: "password12345",
    passwordConfirm: "password12345",
  });

  await pb.createRecord("moderators", {
    email: "mod@test.local",
    password: "password12345",
    passwordConfirm: "password12345",
    level: 3,
  });

  // FULL post — every optional populated, files, multi arrays, json object, geo
  const form = new FormData();
  form.append("title", "Hello World");
  form.append("slug", "hello-world");
  form.append("content", "<h1>hi</h1>");
  form.append("views", "1200");
  form.append("score", "9.5");
  form.append("featured", "true");
  form.append("status", "published");
  form.append("tags", "tech");
  form.append("tags", "news");
  form.append("author", alice.id);
  form.append("contributors", alice.id);
  form.append("contributors", bob.id);
  form.append("category", web.id); // web -> parent tech, enables nested expand
  form.append("homepage", "https://example.com/post");
  form.append("contact_email", "hi@example.com");
  form.append("publish_date", "2026-01-15 10:30:00.000Z");
  form.append("metadata", JSON.stringify({ featuredBy: "editor", pinned: true, order: 3 }));
  form.append("geo", JSON.stringify({ lon: 12.34, lat: 45.67 }));
  form.append("cover", new Blob([new Uint8Array([1, 2, 3])], { type: "image/png" }), "cover.png");
  form.append("gallery", new Blob([new Uint8Array([4, 5, 6])], { type: "image/png" }), "a.png");
  form.append("gallery", new Blob([new Uint8Array([7, 8, 9])], { type: "image/png" }), "b.png");
  const fullPost = await pb.createRecordMultipart("posts", form);

  // MINIMAL post — only required (slug is autogenerated), so optionals return empty sentinels
  await pb.createRecord("posts", { title: "Minimal", status: "draft", author: bob.id });

  // UNICODE / emoji + negative score + deep nested json
  await pb.createRecord("posts", {
    title: "Héllo 世界 🚀 café",
    slug: "unicode-post",
    status: "published",
    author: alice.id,
    score: -3.5,
    tags: ["life", "misc"],
    metadata: { nested: { deep: { list: [1, 2, { flag: true, s: "🌍" }] } }, arr: [{ x: 1 }, { y: 2 }] },
  });

  // BOUNDARY numbers — large safe integer views + high-precision float score
  await pb.createRecord("posts", {
    title: "Boundary numbers",
    slug: "boundary",
    status: "archived",
    author: alice.id,
    views: Number.MAX_SAFE_INTEGER,
    score: 3.141592653589793,
    metadata: [1, 2, 3],
  });

  // team with 2 members (satisfies minSelect: 2) and NO reviewers — the optional
  // minSelect relation comes back as `[]`, which the generated schema must accept.
  await pb.createRecord("teams", { name: "Core", members: [alice.id, bob.id] });

  // one profile per author (unique author index)
  await pb.createRecord("profiles", { author: alice.id, headline: "Engineer" });
  await pb.createRecord("profiles", { author: bob.id });

  // custom-id record (id autogenerated to tk + 8 chars = 10)
  await pb.createRecord("tokens", { label: "api-key" });

  await pb.createRecord("comments", { body: "Nice post!", post: fullPost.id });
  await pb.createRecord("comments", { body: "Second 💬", post: fullPost.id });

  return { alice, bob, tech, web, fullPost };
}
